{"command":"cd /work/workspace && python3 - <<'PY'
import json, re, os
cits=json.load(open('deliverable/citations.json'))
print("entries:", len(cits))
idx=open('library/INDEX.md').read()
rows=[l.split('|') for l in idx.splitlines() if l.startswith('| `')]
index={}
for r in rows:
    f=r[1].strip().strip('`'); status=r[5].strip()
    index[f]=status
print("index files:", len(index))
bad=0
for c in cits:
    lf=c['library_file'].replace('library/','',1)
    ok = lf in index and os.path.exists('library/'+lf)
    st_ok = index.get(lf,'') == c['status_checked']
    if not ok or not st_ok:
        bad+=1; print("PROBLEM", c['library_file'], "exists/known:",ok,"status match:",st_ok, "| index:", index.get(lf), "| mine:", c['status_checked'])
    for k in ("cite","library_file","proposition","status_checked"):
        if k not in c: print("missing key",k,c)
print("problems:", bad)
missing = set(index) - {c['library_file'].replace('library/','',1) for c in cits}
print("index items not cited (memo-bank background only):", sorted(missing))
PY"}
